pub fn needsToReadFile(self: FetchHTTPRequestBody) bool {
            return (switch (self) {
.AnyBlob => |blob| blob.needsToReadFile(),
else => false,
});
    }

pub fn isS3(self: FetchHTTPRequestBody) bool {
